"""3dfp spool -> the Bambu generic filament profile ``bambu_lab.set_filament`` needs."""

import json
import logging
from dataclasses import asdict, dataclass
from importlib import resources

from .mapping import Remote

log = logging.getLogger(__name__)


@dataclass(frozen=True)
class SetFilament:
    tray_info_idx: str
    tray_type: str
    tray_color: str  # RRGGBBAA
    nozzle_temp_min: int
    nozzle_temp_max: int

    def data(self) -> dict:
        return asdict(self)


def load_table() -> dict:
    """The vendored Generic profiles (generated by scripts/extract_profiles.py)."""
    return json.loads(resources.files(__package__).joinpath("generic_profiles.json").read_text())


def _key(s: str) -> str:
    return " ".join(s.split()).casefold()


class Profiles:
    def __init__(self, table: dict, overrides: list[dict]):
        self.table = table
        self._overrides = {}
        for o in overrides:
            if isinstance(o, dict) and isinstance(o.get("filament"), str) \
                    and isinstance(o.get("tray_info_idx"), str) and o["tray_info_idx"]:
                self._overrides[_key(o["filament"])] = o
            else:
                log.warning("ignoring malformed profile override: %r", o)
        # material type -> best id: an id ending "99" (Bambu's main generic), then the
        # shortest (GFU99 over GFSR99), then the lowest
        best: dict[str, str] = {}
        for idx in sorted(table, key=lambda i: (not i.endswith("99"), len(i), i)):
            best.setdefault(str(table[idx]["type"]).upper(), idx)
        self._by_type = best

    def _match(self, material: str) -> str | None:
        m = material.upper().strip()
        if m in self._by_type:
            return self._by_type[m]
        first = m.split()[0].rstrip("+") if m.split() else ""
        return self._by_type.get(first)

    def for_remote(self, r: Remote) -> SetFilament | None:
        color = (r.color_hex or "FFFFFF") + "FF"
        matched = self._match(r.material)
        override = self._overrides.get(_key(f"{r.brand} {r.name}"))
        if override is None:
            if matched is None:
                return None
            e = self.table[matched]
            return SetFilament(matched, e["type"], color, e["nozzle_min"], e["nozzle_max"])
        idx = override["tray_info_idx"]
        e = self.table.get(idx) or (self.table[matched] if matched else None)
        lo, hi = override.get("nozzle_temp_min"), override.get("nozzle_temp_max")
        if e is not None:
            lo = lo if lo is not None else e["nozzle_min"]
            hi = hi if hi is not None else e["nozzle_max"]
        if lo is None or hi is None:
            log.warning("override %s has no nozzle temps and no table entry to borrow", idx)
            return None
        tray_type = e["type"] if e is not None else r.material.upper().strip()
        return SetFilament(idx, tray_type, color, int(lo), int(hi))
